// The brand kit files (generated by scripts/build-assets.ts) must exist with the
// sizes and formats the app stores and browsers require.
import { describe, it, expect } from 'vitest'
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const A = join(__dirname, '..', 'assets')
const pngInfo = (f: string) => {
  const d = readFileSync(join(A, f))
  expect(d.subarray(1, 4).toString()).toBe('PNG')
  return { width: d.readUInt32BE(16), height: d.readUInt32BE(20), colourType: d[25] } // 2 = RGB, 6 = RGBA
}

describe('app icons and splash (Expo / iOS / Android)', () => {
  it('iOS icon: 1024x1024, opaque RGB (App Store rejects alpha)', () => {
    expect(pngInfo('app/icon.png')).toEqual({ width: 1024, height: 1024, colourType: 2 })
  })

  it('Android adaptive layers and themed icon: 1024x1024, transparent where needed', () => {
    for (const f of ['adaptive-foreground.png', 'adaptive-monochrome.png', 'splash-icon.png']) {
      expect(pngInfo(`app/${f}`)).toEqual({ width: 1024, height: 1024, colourType: 6 })
    }
    expect(pngInfo('app/adaptive-background.png')).toMatchObject({ width: 1024, height: 1024 })
  })

  it('Android notification icon: small white silhouette', () => {
    expect(pngInfo('app/notification-icon.png')).toEqual({ width: 96, height: 96, colourType: 6 })
  })
})

describe('web icons', () => {
  it('favicon, Apple touch icon and web app icons at their standard sizes', () => {
    expect(pngInfo('web/favicon-32.png')).toMatchObject({ width: 32, height: 32 })
    expect(pngInfo('web/apple-touch-icon.png')).toEqual({ width: 180, height: 180, colourType: 2 })
    expect(pngInfo('web/icon-192.png')).toMatchObject({ width: 192, height: 192 })
    expect(pngInfo('web/icon-512.png')).toMatchObject({ width: 512, height: 512 })
    expect(pngInfo('web/icon-maskable-512.png')).toMatchObject({ width: 512, height: 512 })
    expect(existsSync(join(A, 'web/favicon.svg'))).toBe(true)
  })
})

describe('logos', () => {
  const svgs = readdirSync(join(A, 'logo')).filter((f) => f.endsWith('.svg'))

  it('every lockup exists in colour, on-dark and one-colour versions', () => {
    for (const kind of ['lockup-horizontal', 'lockup-stacked', 'wordmark']) {
      for (const scheme of ['colour', 'colour-on-dark', 'mono-black', 'mono-white']) {
        expect(svgs).toContain(`${kind}-${scheme}.svg`)
      }
    }
    expect(svgs).toEqual(expect.arrayContaining(['mark.svg', 'mark-mono-black.svg', 'mark-mono-white.svg']))
  })

  it('text is converted to outlines: no <text>, no font dependency, accessible title', () => {
    for (const f of svgs) {
      const s = readFileSync(join(A, 'logo', f), 'utf8')
      expect(s, f).not.toMatch(/<text|font-family|@font-face/)
      expect(s, f).toMatch(/<title>HUFRA حفرة<\/title>/)
      expect(s, f).toMatch(/^<svg xmlns="http:\/\/www.w3.org\/2000\/svg" viewBox="0 0 [\d.]+ [\d.]+"/)
    }
  })

  it('one-colour versions use a single colour', () => {
    for (const f of svgs.filter((n) => n.includes('mono-black'))) {
      const colours = new Set(readFileSync(join(A, 'logo', f), 'utf8').match(/fill="(#[0-9A-Fa-f]{6})"/g))
      expect(colours.size, f).toBe(1)
    }
  })
})

describe('fonts', () => {
  it('Readex Pro static weights are bundled with the SIL Open Font License', () => {
    for (const w of ['Light', 'Regular', 'Medium', 'SemiBold', 'Bold']) {
      expect(readFileSync(join(A, 'fonts', `ReadexPro-${w}.ttf`)).readUInt32BE(0)).toBe(0x00010000) // TrueType
    }
    expect(readFileSync(join(A, 'fonts', 'OFL.txt'), 'utf8')).toContain('SIL Open Font License')
  })
})
